package com.supermarkettracker.infrastructure.persistence.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*; import java.util.UUID;
@Entity @Table(name="dashboard_cache_diario") public class DashboardCacheDiarioEntity { @Id public UUID id; @Column(name="empresa_id",nullable=false) public UUID empresaId; @Column(name="loja_id") public UUID lojaId; @Column(name="referencia_date",nullable=false) public LocalDate dataReferencia; @Column(name="vendas_quantidade",nullable=false) public int quantidadeVendas; @Column(nullable=false,precision=14,scale=2) public BigDecimal faturamento,descontos,lucro,prejuizo; @Column(name="ticket_medio",nullable=false,precision=14,scale=2) public BigDecimal ticketMedio; @Column(name="produtos_vendidos",nullable=false,precision=14,scale=3) public BigDecimal produtosVendidos; @Column(name="ultima_atualizacao",nullable=false) public Instant ultimaAtualizacao; @Column(nullable=false) public long versao; public DashboardCacheDiarioEntity() {} }
